import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Instalación","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/installation.md","filePath":"es/guide/installation.md","lastUpdated":1793173149000}`),a={name:`es/guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to “Instalación”">​</a></h1><p>Sudoku está disponible como app universal en la App Store, compatible con iPhone, iPad y Mac con una sola compra.</p><h2 id="descarga" tabindex="-1">Descarga <a class="header-anchor" href="#descarga" aria-label="Permalink to “Descarga”">​</a></h2><ul><li><strong>App Store</strong>: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">Descargar Sudoku</a> — app universal para iPhone, iPad y Mac</li></ul><h3 id="app-store-recomendado" tabindex="-1">App Store (recomendado) <a class="header-anchor" href="#app-store-recomendado" aria-label="Permalink to “App Store (recomendado)”">​</a></h3><p>La versión de la App Store ofrece actualizaciones automáticas y una integración perfecta en todos tus dispositivos Apple.</p><ul><li><strong>ID de App Store</strong>: 6793606018</li><li><strong>Enlace</strong>: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>Plataformas</strong>: iPhone, iPad, Mac (app universal)</li><li><strong>Precio</strong>: consulta la ficha de la App Store para conocer el precio actual</li></ul><h2 id="pasos-de-instalacion" tabindex="-1">Pasos de instalación <a class="header-anchor" href="#pasos-de-instalacion" aria-label="Permalink to “Pasos de instalación”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Abre la <strong>App Store</strong> en tu dispositivo</li><li>Busca «Sudoku» o usa el enlace directo de arriba</li><li>Toca <strong>Obtener</strong> o <strong>Comprar</strong> para descargar</li><li>La app se instalará automáticamente</li><li>Abre Sudoku desde la pantalla de inicio</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Abre la <strong>App Store</strong> en tu Mac</li><li>Busca «Sudoku» o usa el enlace directo de arriba</li><li>Haz clic en <strong>Obtener</strong> o <strong>Comprar</strong> para adquirirla</li><li>La app se descargará e instalará automáticamente</li><li>Abre Sudoku desde la carpeta Aplicaciones o desde Launchpad</li></ol><h2 id="primer-inicio" tabindex="-1">Primer inicio <a class="header-anchor" href="#primer-inicio" aria-label="Permalink to “Primer inicio”">​</a></h2><p>La primera vez que abras Sudoku, se te pedirá permiso para acceder a iCloud (para la sincronización) y a Game Center (para clasificaciones y logros). Son permisos opcionales: el juego funciona perfectamente sin conexión y sin ellos.</p><h2 id="actualizaciones" tabindex="-1">Actualizaciones <a class="header-anchor" href="#actualizaciones" aria-label="Permalink to “Actualizaciones”">​</a></h2><p>La App Store se encarga de las actualizaciones automáticamente. Para buscar actualizaciones manualmente, abre la App Store y ve a la sección <strong>Cuenta → Actualizaciones</strong>.</p><h2 id="desinstalacion" tabindex="-1">Desinstalación <a class="header-anchor" href="#desinstalacion" aria-label="Permalink to “Desinstalación”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Mantén pulsado el icono de la app Sudoku</li><li>Toca <strong>Eliminar app</strong> → <strong>Borrar app</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Cierra Sudoku</li><li>Arrastra <code>Sudoku.app</code> desde <code>Applications</code> a la papelera</li><li>(Opcional) Elimina los datos de la app:</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to “Requisitos del sistema”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 16.0 o posterior</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) o posterior</li><li><strong>CPU</strong>: Apple Silicon (serie M)</li><li><strong>Memoria</strong>: 2 GB como mínimo</li><li><strong>Almacenamiento</strong>: ~50 MB</li><li><strong>Red</strong>: no es necesaria para jugar (iCloud y Game Center son opcionales)</li></ul><h2 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to “Solución de problemas”">​</a></h2><p>Si tienes problemas durante la instalación:</p><ul><li><strong>macOS bloquea la app</strong>: abre <strong>Ajustes del Sistema → Privacidad y seguridad</strong> y haz clic en <strong>Abrir igualmente</strong> para Sudoku</li><li><strong>La app no aparece</strong>: reinicia la app App Store o tu dispositivo e inténtalo de nuevo</li></ul><p>Para más ayuda, consulta la <a href="./troubleshooting.html">guía de solución de problemas</a> o abre un issue en el repositorio del proyecto.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};